import '@cryptoalgebra/integral-core/contracts/interfaces/IAlgebraPool.sol';
import '@cryptoalgebra/integral-core/contracts/interfaces/IAlgebraPoolDeployer.sol';
import '@cryptoalgebra/integral-periphery/contracts/interfaces/INonfungiblePositionManager.sol';
import '@cryptoalgebra/integral-periphery/contracts/libraries/PoolAddress.sol';

/// @notice Encapsulates the logic for getting info about a NFT token ID
library NFTPositionInfo {
  /// @param deployer The address of the Algebra Deployer used in computing the pool address
  /// @param nonfungiblePositionManager The address of the nonfungible position manager to query
  /// @param tokenId The unique identifier of an Algebra LP token
  /// @return pool The address of the Algebra pool
  /// @return tickLower The lower tick of the Algebra position
  /// @return tickUpper The upper tick of the Algebra position
  /// @return liquidity The amount of liquidity farmd
  function getPositionInfo(
    IAlgebraPoolDeployer deployer,
    INonfungiblePositionManager nonfungiblePositionManager,
    uint256 tokenId
  ) internal view returns (IAlgebraPool pool, int24 tickLower, int24 tickUpper, uint128 liquidity) {
    address token0;
    address token1;
    address pluginDeployer;
    (, , token0, token1, pluginDeployer, tickLower, tickUpper, liquidity, , , , ) = nonfungiblePositionManager.positions(tokenId);

    pool = IAlgebraPool(
      PoolAddress.computeAddress(address(deployer), PoolAddress.PoolKey({deployer: pluginDeployer, token0: token0, token1: token1}))
    );
  }
}

contracts/test/TestERC20.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity =0.8.20;
pragma abicoder v1;

import '@cryptoalgebra/integral-core/contracts/interfaces/IERC20Minimal.sol';

contract TestERC20 is IERC20Minimal {
  mapping(address => uint256) public override balanceOf;
  mapping(address => mapping(address => uint256)) public override allowance;

  constructor(uint256 amountToMint) {
    mint(msg.sender, amountToMint);
  }

  function mint(address to, uint256 amount) public {
    uint256 balanceNext = balanceOf[to] + amount;
    require(balanceNext >= amount, 'overflow balance');
    balanceOf[to] = balanceNext;
  }

  function transfer(address recipient, uint256 amount) external override returns (bool) {
    uint256 balanceBefore = balanceOf[msg.sender];
    require(balanceBefore >= amount, 'insufficient balance');
    balanceOf[msg.sender] = balanceBefore - amount;

    uint256 balanceRecipient = balanceOf[recipient];
    require(balanceRecipient + amount >= balanceRecipient, 'recipient balance overflow');
    if (!isDeflationary) {
      balanceOf[recipient] = balanceRecipient + amount;
    } else {
      balanceOf[recipient] = balanceRecipient + (amount - (amount * 5) / 100);
    }

    emit Transfer(msg.sender, recipient, amount);
    return true;
  }

  function approve(address spender, uint256 amount) external override returns (bool) {
    allowance[msg.sender][spender] = amount;
    emit Approval(msg.sender, spender, amount);
    return true;
  }

  bool isDeflationary = false;
  uint128 transferFeePercent = 5;
  bool overrideNextTransfer;

  uint256 nextTransferAmount;

  function setDefl(bool _isDeflationary, uint128 percent) external {
    isDeflationary = _isDeflationary;
    transferFeePercent = percent;
  }

  function setNextTransferAmount(uint256 _nextTransferAmount) external {
    overrideNextTransfer = true;
    nextTransferAmount = _nextTransferAmount;
  }

  function transferFrom(address sender, address recipient, uint256 amount) external virtual override returns (bool) {
    uint256 allowanceBefore = allowance[sender][msg.sender];
    require(allowanceBefore >= amount, 'allowance insufficient');

    allowance[sender][msg.sender] = allowanceBefore - amount;

    uint256 balanceRecipient = balanceOf[recipient];
    require(balanceRecipient + amount >= balanceRecipient, 'overflow balance recipient');

    if (overrideNextTransfer) {
      amount = nextTransferAmount;
      nextTransferAmount = 0;
      overrideNextTransfer = false;
    }

    if (!isDeflationary) {
      balanceOf[recipient] = balanceRecipient + amount;
    } else {
      balanceOf[recipient] = balanceRecipient + (amount - (amount * uint256(transferFeePercent)) / 100);
    }
    uint256 balanceSender = balanceOf[sender];
    require(balanceSender >= amount, 'underflow balance sender');
    balanceOf[sender] = balanceSender - amount;

    emit Transfer(sender, recipient, amount);
    return true;
  }
}

contracts/test/TestERC20Reentrant.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity =0.8.20;

import '../interfaces/IAlgebraEternalFarming.sol';
import '../base/IncentiveKey.sol';
import './TestERC20.sol';

contract TestERC20Reentrant is TestERC20 {
  bool public doReentrancy = false;
  bool public doComplexReentrancy = false;

  IncentiveKey private keyForAttack;
  uint128 rewardAmountForAttack;
  uint128 bonusRewardAmountForAttack;

  address addressForComplexAttack;
  bytes calldataForComplexAttack;

  constructor(uint256 amountToMint) TestERC20(amountToMint) {
    //
  }

  function prepareAttack(IncentiveKey memory key, uint128 rewardAmount, uint128 bonusRewardAmount) external {
    doReentrancy = true;
    keyForAttack = key;
    rewardAmountForAttack = rewardAmount;
    bonusRewardAmountForAttack = bonusRewardAmount;
  }

  function prepareComplexAttack(address target, bytes calldata data) external {
    doComplexReentrancy = true;
    addressForComplexAttack = target;
    calldataForComplexAttack = data;
  }

  function cancelComplexAttack() external {
    doComplexReentrancy = false;
  }

  function transferFrom(address sender, address recipient, uint256 amount) external override returns (bool) {
    if (doReentrancy) {
      IAlgebraEternalFarming(msg.sender).addRewards(keyForAttack, rewardAmountForAttack, bonusRewardAmountForAttack);
    }

    if (doComplexReentrancy) {
      (bool res, ) = addressForComplexAttack.call(calldataForComplexAttack);
      require(res, 'Attack failed');
    }

    uint256 allowanceBefore = allowance[sender][msg.sender];
    require(allowanceBefore >= amount, 'allowance insufficient');

    allowance[sender][msg.sender] = allowanceBefore - amount;

    uint256 balanceRecipient = balanceOf[recipient];
    require(balanceRecipient + amount >= balanceRecipient, 'overflow balance recipient');

    if (overrideNextTransfer) {
      amount = nextTransferAmount;
      nextTransferAmount = 0;
      overrideNextTransfer = false;
    }

    if (!isDeflationary) {
      balanceOf[recipient] = balanceRecipient + amount;
    } else {
      balanceOf[recipient] = balanceRecipient + (amount - (amount * uint256(transferFeePercent)) / 100);
    }
    uint256 balanceSender = balanceOf[sender];
    require(balanceSender >= amount, 'underflow balance sender');
    balanceOf[sender] = balanceSender - amount;

    emit Transfer(sender, recipient, amount);
    return true;
  }
}

